public class GameMain extends Game {
    public static final double CX = 640, CY = 400, RX = 440, RY = 260;
    public TileMap track;
    public GameObject player;
    public double raceTime;
    public boolean finished;

    @Override public void onCreate() { build(); }

    @Override public void onUpdate(double delta) {
        if (!finished) raceTime += delta;
        if (input.isKeyPressed(Keys.R)) build();
    }

    public boolean isRoad(double x, double y) {
        String tile = track == null ? null : track.tileAt(x, y);
        return Assets.DIRT.key().equals(tile);
    }

    private void gate(int index, double angleDeg) {
        double rad = Math.toRadians(angleDeg);
        double x = CX + Math.cos(rad) * RX, y = CY + Math.sin(rad) * RY;
        double nx = Math.cos(rad) * RX * RY, ny = Math.sin(rad) * RY * RX;
        double len = Math.hypot(nx, ny);
        GameObject gate = createObject("Gate").setPosition(x, y);
        Collider2D area = gate.addComponent(new Collider2D(Math.abs(nx / len) * 140 + 24, Math.abs(ny / len) * 140 + 24).asTrigger());
        gate.addComponent(new Gate(index));
    }

    private void racer(Assets sprite, double angleDeg, boolean human) {
        double rad = Math.toRadians(angleDeg);
        double x = CX + Math.cos(rad) * RX, y = CY + Math.sin(rad) * RY;
        GameObject kart = createObject(human ? "Player" : "AiKart").setPosition(x, y);
        kart.addComponent(new Sprite(sprite, 30, 30));
        kart.addComponent(new CircleCollider2D(10));
        kart.transform.rotation = rad + Math.PI / 2;
        if (human) {
            kart.addComponent(new KartController());
            kart.addComponent(new LapTracker());
            player = kart;
        } else {
            kart.addComponent(new AiKart(angleDeg));
        }
    }

    private void build() {
        for (GameObject o : new java.util.ArrayList<>(getObjects())) o.destroy();
        raceTime = 0; finished = false;
        setWorldBounds(0, 0, 1280, 800);

        GameObject ground = createObject("Ground");
        track = ground.addComponent(new TileMap(Assets.GRASS, 32));
        track.generate(40, 25, 5, Assets.GRASS, Assets.GRASS, Assets.GRASS_TUFT);
        for (int c = 0; c < 40; c++)
            for (int r = 0; r < 25; r++) {
                double x = c * 32 + 16, y = r * 32 + 16;
                double v = (x - CX) * (x - CX) / (RX * RX) + (y - CY) * (y - CY) / (RY * RY);
                if (v > 0.55 && v < 1.35) track.setTile(c, r, Assets.DIRT);
            }

        gate(0, -90);
        gate(1, 30);
        gate(2, 150);
        gate(3, 90);

        racer(Assets.PLAYER01, -95, true);
        racer(Assets.RANGER, -90, false);
        racer(Assets.ROGUE, -85, false);

        GameObject camera = createObject("Camera");
        camera.addComponent(new Camera2D()).follow(player);
    }

    @Override public void onDrawUI() {
        LapTracker lap = player == null || player.destroyed ? null : player.getComponent(LapTracker.class);
        KartController kart = player == null || player.destroyed ? null : player.getComponent(KartController.class);
        canvas.drawText("Okrazenie " + (lap == null ? 1 : Math.min(3, lap.laps + 1)) + "/3   "
            + (kart == null ? 0 : (int) Math.abs(kart.speed * 3.6)) + " km/h   "
            + (Math.round(raceTime * 10) / 10.0) + " s", 320, 18, 16, "#ffe080", "center", "middle");
        if (finished) canvas.drawText("META! Czas " + (Math.round(raceTime * 10) / 10.0) + " s — R restartuje", 320, 60, 24, "#7cfc90", "center", "middle");
    }
}

