public class KartController extends Component {
    public double speed, heading = -Math.PI / 2;
    public double maxRoad = 260, maxGrass = 130;
    @Override public void onCreate() { heading = transform.rotation; }
    @Override public void onUpdate(double delta) {
        GameMain game = (GameMain) getGame();
        double throttle = (getGame().input.isKeyDown(Keys.W) || getGame().input.isKeyDown(Keys.UP) ? 1 : 0)
                        - (getGame().input.isKeyDown(Keys.S) || getGame().input.isKeyDown(Keys.DOWN) ? 1 : 0);
        double steer = (getGame().input.isKeyDown(Keys.D) || getGame().input.isKeyDown(Keys.RIGHT) ? 1 : 0)
                     - (getGame().input.isKeyDown(Keys.A) || getGame().input.isKeyDown(Keys.LEFT) ? 1 : 0);
        boolean road = game.isRoad(transform.x, transform.y);
        speed += throttle * (road ? 320 : 180) * delta;
        speed -= speed * (road ? 0.6 : 2.2) * delta;
        double cap = road ? maxRoad : maxGrass;
        speed = Math.max(-80, Math.min(cap, speed));
        heading += steer * delta * (2.4 * Math.min(1, Math.abs(speed) / 80)) * (speed >= 0 ? 1 : -1);
        transform.x += Math.cos(heading) * speed * delta;
        transform.y += Math.sin(heading) * speed * delta;
        transform.x = Math.max(24, Math.min(1256, transform.x));
        transform.y = Math.max(24, Math.min(776, transform.y));
        transform.rotation = heading;
    }
}

