public class LapTracker extends Component {
    public int next, laps;
    @Override public void onTrigger(GameObject other) {
        Gate gate = other.getComponent(Gate.class);
        if (gate == null || gate.index != next) return;
        next++;
        getGame().audio.playNote(next >= 4 ? "C7" : "E5", 0.1, "square");
        if (next >= 4) {
            next = 0;
            laps++;
            if (laps >= 3) ((GameMain) getGame()).finished = true;
        }
    }
}

