public class AiKart extends Component {
    public double angle, speed;
    public AiKart(double startAngleDeg) { angle = Math.toRadians(startAngleDeg); speed = 150; }
    @Override public void onCreate() { speed = 150 + gameObject.id % 40; }
    @Override public void onUpdate(double delta) {
        GameMain game = (GameMain) getGame();
        double turnRate = speed / (game.isRoad(transform.x, transform.y) ? 420 : 700);
        angle += turnRate * delta;
        double targetHeading = angle + Math.PI / 2;
        double diff = targetHeading - transform.rotation;
        while (diff > Math.PI) diff -= Math.PI * 2;
        while (diff < -Math.PI) diff += Math.PI * 2;
        transform.rotation += Math.max(-3 * delta, Math.min(3 * delta, diff));
        transform.x = GameMain.CX + Math.cos(angle) * GameMain.RX;
        transform.y = GameMain.CY + Math.sin(angle) * GameMain.RY;
    }
}
